-- 2. Atualizar o saldo total dos afiliados
UPDATE afiliados SET total_vendas = (SELECT count(*) FROM indicacoes WHERE afiliado_id = '39328a55-110b-40c7-aecd-2cc98f01c3f7' AND converteu = true), total_ganhos = (SELECT COALESCE(SUM(comissao), 0) FROM indicacoes WHERE afiliado_id = '39328a55-110b-40c7-aecd-2cc98f01c3f7' AND converteu = true) WHERE id = '39328a55-110b-40c7-aecd-2cc98f01c3f7';
